import math

def parse_amount(text):
    # strip leading/trailing whitespace
    text = text.strip()
    # reject empty
    if not text:
        raise ValueError()
    # reject negative numbers (excluding '-0')
    if text.startswith('-') and text != '-0':
        raise ValueError()
    # replace comma with dot for decimal separator
    if ',' in text:
        text = text.replace(',', '.')
    # parse float
    try:
        value = float(text)
    except ValueError:
        raise ValueError()
    # reject non-finite values (nan, inf, -inf)
    if not math.isfinite(value):
        raise ValueError()
    return value
